-- PROPOSED — NOT APPLIED. NATIVE-SCRIPT DRAFTS, EACH ROW NEEDS NATIVE REVIEW + OWNER APPROVAL.
--
-- Round 8 (2026-10-06, owner: "every language gets an automatic response").
-- Today only English and Spanish have active + safe_for_auto_reply reply
-- templates; every other language's catalog rows are romanised drafts with
-- safe_for_auto_reply = false. These are NATIVE-SCRIPT drafts for the core
-- seller flow in the 9 non-Latin / tonal languages:
--   S1 ownership_check, S2 consider_selling, S3 seller_asking_price,
--   S4 ask_condition_clarifier, not_interested (30-day nurture),
--   seller_frustration_apology, price_reality_check.
-- who_is_this (native, lc-ap2-wis2-*) and ownership_connection_clarifier
-- (native, lc-ap2-ocl-*) are already drafted in
-- PROPOSED_20261006090000_seller_autopilot_v2_templates.sql.
--
-- EVERY row is inserted INACTIVE and NOT safe_for_auto_reply, with
-- metadata.needs_native_review = true. Nothing can send from this file.
-- Activate per language after a native speaker signs off, e.g.:
--   update public.sms_templates set is_active = true, safe_for_auto_reply = true, updated_at = now()
--    where template_id like 'lc-native-%-zh-1';
-- Placeholders: {{seller_first_name}}, {{agent_name}}, {{property_address}}
-- (S1 only), the same as the English rows. Idempotent insert by template_id.

begin;
set local lock_timeout = '5s';

insert into public.sms_templates (
  use_case, template_id, template_name, language, agent_persona, template_body,
  english_translation, variables, is_active, safe_for_auto_reply, reply_mode,
  identity_contact_mode, property_type_scope, stage_code, stage_label,
  is_first_touch, is_follow_up, fallback_rank, quarantine_state, metadata
)
select v.use_case, v.template_id, v.template_name, v.language, 'Alex', v.template_body,
       v.english_translation, '{}'::jsonb, false, false,
       case when v.is_first_touch then 'manual' else 'auto_reply' end,
       'neutral', 'Any Residential', v.stage_code, v.stage_label,
       v.is_first_touch, false, 1, 'active',
       jsonb_build_object(
         'authored_by', 'reply_quality_round8_2026_10_06',
         'approval_status', 'proposed_pending_native_review',
         'needs_native_review', true,
         'script', 'native'
       )
from (values
  ('ownership_check', 'lc-native-own-zh-1', 'ownership_check — Mandarin (native script, round 8)', 'Mandarin', '{{seller_first_name}}您好，我是{{agent_name}}。请问您还是{{property_address}}的业主吗？', 'Hi {{seller_first_name}}, this is {{agent_name}}. Are you still the owner of {{property_address}}?', 'S1', 'Stage 1 Ownership Confirmation', true),
  ('consider_selling', 'lc-native-cs-zh-1', 'consider_selling — Mandarin (native script, round 8)', 'Mandarin', '谢谢您的确认。您会考虑我们为这处房产提出的报价吗？', 'Thanks for confirming. Would you consider a proposal for the property?', 'S2', 'Stage 2 Consider Selling', false),
  ('seller_asking_price', 'lc-native-ap-zh-1', 'seller_asking_price — Mandarin (native script, round 8)', 'Mandarin', '明白了。您心目中这处房产的价格大概是多少？', 'Got it. What price would you have in mind for the property?', 'S3', 'Stage 3 Seller Asking Price', false),
  ('ask_condition_clarifier', 'lc-native-cond-zh-1', 'ask_condition_clarifier — Mandarin (native script, round 8)', 'Mandarin', '谢谢。能再多介绍一下房子的状况吗？比如屋顶、空调暖气或地基有没有大问题？', 'Thanks, could you tell me a little more about the condition? Anything major like roof, HVAC, or foundation?', 'S4', 'Stage 4 Condition Clarifier', false),
  ('not_interested', 'lc-native-ni-zh-1', 'not_interested — Mandarin (native script, round 8)', 'Mandarin', '明白，我不再打扰。如果以后情况有变，需要我过一段时间再联系您吗？', 'Understood, I''ll leave it alone. If that ever changes, want me to check back down the road?', 'SP', 'Not Interested (30-day nurture)', false),
  ('seller_frustration_apology', 'lc-native-sfa-zh-1', 'seller_frustration_apology — Mandarin (native script, round 8)', 'Mandarin', '抱歉，我记下了。谢谢您告诉我。', 'Sorry about that, I''ll note it. Thanks for letting me know.', null, 'Frustration Apology', false),
  ('price_reality_check', 'lc-native-prc-zh-1', 'price_reality_check — Mandarin (native script, round 8)', 'Mandarin', '哈，那就好了！说实话，如果价格合理，您会考虑出售吗？', 'Ha, I wish! Realistically, if the number made sense, is selling something you''d consider?', null, 'Price Reality Check', false),
