  ('consider_selling', 'lc-native-cs-vi-1', 'consider_selling — Vietnamese (native script, round 8)', 'Vietnamese', 'Cảm ơn anh/chị đã xác nhận. Anh/chị có cân nhắc một đề nghị mua cho bất động sản này không?', 'Thanks for confirming. Would you consider a proposal for the property?', 'S2', 'Stage 2 Consider Selling', false),
  ('seller_asking_price', 'lc-native-ap-vi-1', 'seller_asking_price — Vietnamese (native script, round 8)', 'Vietnamese', 'Tôi hiểu rồi. Anh/chị nghĩ giá bao nhiêu cho bất động sản này?', 'Got it. What price would you have in mind for the property?', 'S3', 'Stage 3 Seller Asking Price', false),
  ('ask_condition_clarifier', 'lc-native-cond-vi-1', 'ask_condition_clarifier — Vietnamese (native script, round 8)', 'Vietnamese', 'Cảm ơn. Anh/chị có thể cho tôi biết thêm về tình trạng nhà không? Có vấn đề lớn nào như mái, điều hòa hay móng không?', 'Thanks, could you tell me a little more about the condition? Anything major like roof, HVAC, or foundation?', 'S4', 'Stage 4 Condition Clarifier', false),
  ('not_interested', 'lc-native-ni-vi-1', 'not_interested — Vietnamese (native script, round 8)', 'Vietnamese', 'Tôi hiểu, tôi sẽ không làm phiền nữa. Nếu sau này có gì thay đổi, anh/chị có muốn tôi liên lạc lại không?', 'Understood, I''ll leave it alone. If that ever changes, want me to check back down the road?', 'SP', 'Not Interested (30-day nurture)', false),
  ('seller_frustration_apology', 'lc-native-sfa-vi-1', 'seller_frustration_apology — Vietnamese (native script, round 8)', 'Vietnamese', 'Xin lỗi về điều đó, tôi đã ghi lại. Cảm ơn anh/chị đã cho tôi biết.', 'Sorry about that, I''ll note it. Thanks for letting me know.', null, 'Frustration Apology', false),
  ('price_reality_check', 'lc-native-prc-vi-1', 'price_reality_check — Vietnamese (native script, round 8)', 'Vietnamese', 'Haha, ước gì được vậy! Nói thật, nếu giá hợp lý thì anh/chị có cân nhắc bán không?', 'Ha, I wish! Realistically, if the number made sense, is selling something you''d consider?', null, 'Price Reality Check', false),
  ('ownership_check', 'lc-native-own-ko-1', 'ownership_check — Korean (native script, round 8)', 'Korean', '안녕하세요 {{seller_first_name}}님, {{agent_name}}입니다. 아직 {{property_address}}의 소유주이신가요?', 'Hi {{seller_first_name}}, this is {{agent_name}}. Are you still the owner of {{property_address}}?', 'S1', 'Stage 1 Ownership Confirmation', true),
