  ('ownership_check', 'lc-native-own-hi-1', 'ownership_check — Indian (Hindi or Other) (native script, round 8)', 'Indian (Hindi or Other)', 'नमस्ते {{seller_first_name}}, मैं {{agent_name}} बोल रहा हूँ। क्या आप अभी भी {{property_address}} के मालिक हैं?', 'Hi {{seller_first_name}}, this is {{agent_name}}. Are you still the owner of {{property_address}}?', 'S1', 'Stage 1 Ownership Confirmation', true),
  ('consider_selling', 'lc-native-cs-hi-1', 'consider_selling — Indian (Hindi or Other) (native script, round 8)', 'Indian (Hindi or Other)', 'पुष्टि करने के लिए धन्यवाद। क्या आप इस प्रॉपर्टी के लिए एक प्रस्ताव पर विचार करेंगे?', 'Thanks for confirming. Would you consider a proposal for the property?', 'S2', 'Stage 2 Consider Selling', false),
  ('seller_asking_price', 'lc-native-ap-hi-1', 'seller_asking_price — Indian (Hindi or Other) (native script, round 8)', 'Indian (Hindi or Other)', 'समझ गया। इस प्रॉपर्टी के लिए आपके मन में क्या कीमत है?', 'Got it. What price would you have in mind for the property?', 'S3', 'Stage 3 Seller Asking Price', false),
  ('ask_condition_clarifier', 'lc-native-cond-hi-1', 'ask_condition_clarifier — Indian (Hindi or Other) (native script, round 8)', 'Indian (Hindi or Other)', 'धन्यवाद। क्या आप प्रॉपर्टी की हालत के बारे में थोड़ा और बता सकते हैं? छत, एसी/हीटिंग या नींव जैसी कोई बड़ी समस्या है?', 'Thanks, could you tell me a little more about the condition? Anything major like roof, HVAC, or foundation?', 'S4', 'Stage 4 Condition Clarifier', false),
  ('not_interested', 'lc-native-ni-hi-1', 'not_interested — Indian (Hindi or Other) (native script, round 8)', 'Indian (Hindi or Other)', 'समझ गया, मैं आपको परेशान नहीं करूँगा। अगर आगे कुछ बदलता है, तो क्या मैं बाद में फिर संपर्क करूँ?', 'Understood, I''ll leave it alone. If that ever changes, want me to check back down the road?', 'SP', 'Not Interested (30-day nurture)', false),
  ('seller_frustration_apology', 'lc-native-sfa-hi-1', 'seller_frustration_apology — Indian (Hindi or Other) (native script, round 8)', 'Indian (Hindi or Other)', 'इसके लिए माफ़ी चाहता हूँ, मैंने नोट कर लिया है। बताने के लिए धन्यवाद।', 'Sorry about that, I''ll note it. Thanks for letting me know.', null, 'Frustration Apology', false),
  ('price_reality_check', 'lc-native-prc-hi-1', 'price_reality_check — Indian (Hindi or Other) (native script, round 8)', 'Indian (Hindi or Other)', 'हाहा, काश! सच कहूँ तो, अगर कीमत सही हो, तो क्या आप बेचने पर विचार करेंगे?', 'Ha, I wish! Realistically, if the number made sense, is selling something you''d consider?', null, 'Price Reality Check', false)
) as v(use_case, template_id, template_name, language, template_body, english_translation, stage_code, stage_label, is_first_touch)
where not exists (select 1 from public.sms_templates t where t.template_id = v.template_id);

commit;

